
(() => {
  const ENTERPRISE_SOLUTION = "data:image/webp;base64,";
  const $ = (s,r=document) => r.querySelector(s);
  const $$ = (s,r=document) => Array.from(r.querySelectorAll(s));
  const ready = fn => document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded',fn,{once:true}) : setTimeout(fn,0);

  function labelFor(el) { return (el?.querySelector('h3')?.textContent || el?.getAttribute('aria-label') || 'media').trim(); }
  function slideNo(slide, fallback) {
    const img = $('img', slide);
    const text = [slide.dataset.slide, slide.dataset.index, img?.alt, slide.getAttribute('aria-label'), slide.textContent].filter(Boolean).join(' ');
    const match = text.match(/(?:slide|frame|image|page|\b)(?:\s*0*)?(\d+)\b/i) || text.match(/\b(\d(1, 2))\b/);
    return match ? Number(match[1]) : fallback;
  }
  function setRatio(stage, image) {
    if(!stage || !image) return;
    const apply = () => {
      const w = image.naturalWidth || image.width, h = image.naturalHeight || image.height;
      if(w && h) stage.style.aspectRatio = w + ' / ' + h;
    };
    image.complete ? apply() : image.addEventListener('load', apply, {once:true});
  }
  function removeLegacyControls(card) {
    $$('.final-carousel-button,.archive-carousel-controls,.archive-carousel-button,[data-refined-carousel-prev],[data-refined-carousel-next],[data-archive-carousel-prev],[data-archive-carousel-next],[data-personal-carousel-prev],[data-personal-carousel-next]', card).forEach(n=>n.remove());
  }
  function installCarousel(card, kind='archive') {
    if(!card) return;
    const stage = $('.archive-carousel-stage',card);
    const viewport = $('[data-archive-carousel],.archive-carousel-preview,.archive-carousel-preview',card);
    const rail = viewport && $('.archive-carousel-rail', viewport);
    if(!stage || !viewport || !rail) return;
    stage.removeAttribute('data-final-carousel'); viewport.removeAttribute('data-final-carousel');
    stage.classList.add('v4-carousel-stage');
    if(kind==='instagram') stage.classList.add('v4-instagram-stage');
    if(kind==='deck') stage.classList.add('v4-deck-stage');
    if(kind==='gathering') stage.classList.add('v4-gathering-stage');
    removeLegacyControls(card);
    const slides = $$('.archive-carousel-slide',rail)
      .map((node,i)=>({node,i})).sort((a,b)=>slideNo(a.node,a.i)-slideNo(b.node,b.i));
    slides.forEach(item=>rail.appendChild(item.node));
    if(slides.length < 2) return;
    slides.forEach(item=>{const img=$('img',item.node);if(img){img.loading='eager';setRatio(stage,img);}});
    let index = 0, pointer = null;
    const render = () => { rail.style.transform = `translate3d(${-index*100}%,0,0)`; };
    const button = (dir, label, icon) => {
      const b = document.createElement('button');
      b.type='button'; b.className='v4-carousel-button '+dir;
      b.setAttribute('aria-label',label); b.innerHTML=`<span class="material-symbols-rounded" aria-hidden="true">${icon}</span>`;
      b.addEventListener('click', e=>{e.preventDefault();e.stopPropagation();index=(index+(dir==='next'?1:-1)+slides.length)%slides.length;render();});
      stage.appendChild(b);
    };
    button('prev','Previous slide','chevron_left'); button('next','Next slide','chevron_right');
    viewport.addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY,id:e.pointerId};viewport.setPointerCapture?.(e.pointerId);});
    viewport.addEventListener('pointerup',e=>{if(!pointer) return; const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y; pointer=null;if(Math.abs(dx)>34 && Math.abs(dx)>Math.abs(dy)){index=(index+(dx<0?1:-1)+slides.length)%slides.length;render();}});
    viewport.addEventListener('pointercancel',()=>pointer=null);
    render();
  }

  function targetCard(root, heading) { return $$(root+' h3').find(h=>h.textContent.trim()===heading)?.closest('article,.personal-content-card'); }
  function setupCarousels() {
    const root = '#sddToolsView';
    installCarousel(targetCard(root,'SDD Instagram Content System'),'instagram');
    installCarousel(targetCard(root,'SDD Employee Gathering'),'gathering');
    installCarousel(targetCard(root,'Golf Halalbihalal Announcement'),'archive');
    const deck = targetCard(root,'Service Presentation Deck');
    const deckStage = deck && $('.archive-work-stage',deck); if(deckStage) deckStage.classList.add('v4-deck-stage');
  }

  function decodeDataUri(uri, type) {
    const comma = uri.indexOf(','); if(comma<0) return null;
    const raw = atob(uri.slice(comma+1)), size = 1024*1024, parts=[];
    for(let i=0;i<raw.length;i+=size){ const part=raw.slice(i,i+size), bytes=new Uint8Array(part.length); for(let j=0;j<part.length;j++) bytes[j]=part.charCodeAt(j); parts.push(bytes); }
    return URL.createObjectURL(new Blob(parts,{type:type||'video/mp4'}));
  }
  function mediaUri(video) {
    const source = $('source',video);
    return source?.dataset.videoSrc || source?.dataset.src || source?.getAttribute('src') || video.dataset.videoSrc || video.dataset.mediaSrc || video.dataset.src || video.getAttribute('src') || '';
  }
  function installVideoControls() {
    const all = $$('video').filter(v=>!v.loop && !v.closest('[data-project-hero]') && v.dataset.autoplay!=='true');
    all.forEach(video=>{
      const host = video.parentElement; if(!host || host.dataset.v4VideoReady) return;
      const uri = mediaUri(video); if(!uri) return;
      host.dataset.v4VideoReady='true'; host.classList.add('v4-video-host');
      $$('.final-video-control,.portfolio-reel-control,.personal-reel-control,[data-portfolio-reel-control]',host).forEach(n=>n.remove());
      const btn=document.createElement('button'); btn.type='button'; btn.className='v4-video-control'; btn.textContent='Play'; btn.setAttribute('aria-label','Play video'); host.appendChild(btn);
      video.muted=true; video.playsInline=true; video.preload='metadata';
      let loaded = !!video.src && !video.src.startsWith('data:');
      let blob = '';
      const ensure = () => {
        if(loaded) return Promise.resolve();
        return new Promise((resolve,reject)=>{
          try {
            blob = uri.startsWith('data:') ? decodeDataUri(uri,'video/mp4') : uri;
            if(!blob) throw new Error('Missing video source');
            video.src=blob; video.load(); loaded=true;
            const done=()=>resolve(); const fail=()=>reject(new Error('Video cannot be loaded'));
            video.addEventListener('canplay',done,{once:true}); video.addEventListener('error',fail,{once:true});
          } catch(error) { reject(error); }
        });
      };
      const sync=()=>{const playing=!video.paused&&!video.ended;btn.textContent=playing?'Pause':'Play';btn.setAttribute('aria-label',playing?'Pause video':'Play video');};
      btn.addEventListener('click',async e=>{
        e.preventDefault();e.stopPropagation();
        try { if(!loaded){btn.textContent='Loading';await ensure();} if(video.paused||video.ended) await video.play(); else video.pause(); sync(); } catch(err) {btn.textContent='Play';}
      });
      video.addEventListener('play',sync);video.addEventListener('pause',sync);video.addEventListener('ended',sync);sync();
    });
  }

  function updateEnterprise() {}
  function updateHome() {
    const title=$('#homeView .hero-title'); if(title) title.innerHTML='<span class="v4-hero-line">YOGENDRA</span><span class="v4-hero-line">CHAUDHARY <span class="v4-hero-dash" aria-hidden="true">—</span></span><span class="v4-hero-line v4-hero-line--role">PRODUCT DESIGNER</span>';
    const copy=$('#heroCopy'); if(copy){
      copy.setAttribute('aria-label',"A UI/UX and Product Designer focused on intuitive software interfaces, reusable components, and user-centered workflows\u2014turning complex product requirements into clear, usable experiences that people can navigate with confidence.");
      copy.innerHTML="<span class=\"hero-copy-group\">A UI/UX and Product Designer</span><span class=\"hero-copy-group\">focused on intuitive software interfaces and reusable components</span><span class=\"hero-copy-group\">\u2014turning complex product requirements into clear workflows</span><span class=\"hero-copy-group\">and usable experiences people can navigate with confidence.</span>";
    }
  }
  
  function resetHomeWorkFilterOnTopNav() {
    $$('header a[href="#work"],#siteHeader a[href="#work"],.nav-links a[href="#work"]').forEach(a=>a.addEventListener('click',()=>setTimeout(()=>$('#homeView [data-filter="all"]')?.click(),0)));
  }
  function boot() {
    updateEnterprise(); updateHome();  setupCarousels(); installVideoControls(); resetHomeWorkFilterOnTopNav();
    document.documentElement.dataset.v4Ready='true'; window.dispatchEvent(new Event('portfolio:v4ready'));
  }
  ready(boot);
})();
